-- Shortest Distances from Node 1 (Hard)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$shortest-distances$q$, $q$Shortest Distances from Node 1$q$, $q$An undirected, weighted graph has n nodes numbered 1 to n. Find the length of the shortest path from node 1 to every node.

For a node that cannot be reached, print -1. The graph may contain parallel edges and self-loops.$q$, $q$Hard$q$, $q$Graphs$q$, 'code', ARRAY[$q$graph$q$, $q$dijkstra$q$, $q$heap$q$, $q$shortest-path$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n and m.\n    # Next m lines: u, v, w describing an undirected edge of weight w.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n and m.\n// Next m lines: u, v, w describing an undirected edge of weight w.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n and m.\n        // Next m lines: u, v, w describing an undirected edge of weight w.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n and m.\n    // Next m lines: u, v, w describing an undirected edge of weight w.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n and m.\n    // Next m lines: u, v, w describing an undirected edge of weight w.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "4 4\n1 2 1\n2 3 1\n1 3 5\n3 4 1", "output": "0 1 2 3", "explanation": "The route 1-2-3 costs 2, cheaper than the direct edge of 5."}, {"input": "3 1\n1 2 5", "output": "0 5 -1", "explanation": "Node 3 is not connected to node 1."}]$q$::jsonb, ARRAY[$q$1 ≤ n ≤ 4 000$q$, $q$0 ≤ m ≤ 10 000$q$, $q$1 ≤ w ≤ 10^9 (path lengths can exceed 32-bit integers)$q$]::text[], 50, 1017, 2000, 262144, $q$Line 1: n and m.
Next m lines: u, v, w describing an undirected edge of weight w.$q$, $q$One line with n integers: the distance from node 1 to nodes 1, 2, …, n.$q$, $q$All weights are positive, so Dijkstra's algorithm applies. Keep a min-heap of (distance, node). Pop the closest node; skip it if the popped distance is stale. Relax each neighbour. Use 64-bit integers (long in Java, long long in C++): sums reach 10^13. With a heap the cost is O((n + m) log n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

